from pathlib import Path
import json,html,zipfile
R=Path(__file__).resolve().parents[1];D=R/'processed';S=json.loads((D/'sources.json').read_text());O=json.loads((D/'offices.geojson').read_text())['features'];E=html.escape
rows=[('Fond photo','ign','Flux fonctionnel sur Suresnes. Images aériennes 2024, résolution native 20 cm.'),('Zonages PLU','plu','55 polygones valides, 21 libellés. Document 92073_PLU_20240626, indiqué en vigueur.'),('Transports structurants','transport','3 stations physiques : Suresnes–Mont-Valérien (L/U), Suresnes–Longchamp et Belvédère (T2). Pas de métro dans cet extrait communal.'),('Santé et scolarité','education','30 établissements scolaires ouverts : 23 écoles, 5 collèges, 2 lycées. Une position corrigée avec la BAN.'),('Santé et pharmacies','health','13 structures de soins sélectionnées et 13 pharmacies ; ces dernières figurent dans les aménités de quartier.'),('Commerces de quartier','osm','18 boulangeries. 13 pharmacies OSM également récupérées, mais non ajoutées aux pharmacies FINESS afin d’éviter les doubles comptes.'),('Bureaux','broker','10 cartes d’annonces observées ; test limité à 5 fiches avec adresse. 3 autres annonces sans adresse exclues du repérage. Disponibilité immédiate déclarée, vacance non confirmée.')]
tr=''.join(f'<tr><td>{E(label)}</td><td><a href="{E(S[k]["url"])}">{E(S[k]["name"])}</a><small>{E(S[k]["format"])}<br>{E(S[k]["license"])}</small></td><td>{E(text)}<small>{E(S[k]["vintage"])}</small></td></tr>' for label,k,text in rows)
ot=''.join(f'<tr><td><a href="{E(f["properties"]["source_url"])}">{E(f["properties"]["address"])}</a></td><td>{E(f["properties"]["surface_label"])}</td><td>{len(f["properties"]["nearby"])}</td></tr>' for f in O)
body=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suresnes — test des six couches de données</title><style>body{{font:15px/1.65 system-ui,sans-serif;max-width:1100px;margin:48px auto;padding:0 24px;color:#183d36;background:#fafbf9}}h1{{font-size:34px;line-height:1.2}}h2{{font-size:21px;margin-top:34px}}p,li{{color:#45655b}}table{{width:100%;border-collapse:collapse;font-size:13px}}td,th{{text-align:left;padding:15px 12px;border-bottom:1px solid #dae4dc;vertical-align:top}}th{{background:#eef4ed;font-size:11px;text-transform:uppercase}}small{{display:block;color:#728178;margin-top:8px}}a{{color:#176c51}}.badge{{color:#5d7f70;font-size:12px;text-transform:uppercase;letter-spacing:1px}}.cta{{display:inline-block;padding:12px 18px;background:#205d49;color:white;border-radius:7px;text-decoration:none}}.notice{{padding:18px;background:#f5eddd;border-radius:9px}}footer{{border-top:1px solid #d9e3db;padding:22px 0;margin-top:36px;font-size:12px}}@media(max-width:700px){{body{{padding:0 14px}}td,th{{padding:10px 6px;font-size:11px}}h1{{font-size:27px}}}}</style></head><body><span class="badge">Test réalisé le 19 octobre 2026 · commune 92073</span><h1>Les données nécessaires à une carte de Suresnes</h1><p>Les six besoins ont été testés par extraction réelle. La carte rassemble le fond aérien et cinq groupes activables : PLU, transports, santé/scolarité, bureaux et aménités de quartier.</p><a class="cta" href="https://suresnes-carte-couches.francois-a-allain.chatgpt.site/">Ouvrir la carte interactive ↗</a><h2>Sources retenues et résultats du test</h2><table><thead><tr><th>Besoin</th><th>Source et accès</th><th>Résultat et millésime</th></tr></thead><tbody>{tr}</tbody></table><p>Le fond IGN est une <strong>orthophotographie aérienne</strong>, le rendu adapté au besoin de fond « satellite ». Le <a href="{S['ign']['date_url']}">tableau IGN des prises de vues</a> donne 2024 et 20 cm pour les Hauts-de-Seine. Les services ouverts testés ne nécessitaient ni abonnement ni clé. Leurs conditions et quotas restent ceux des producteurs.</p><h2>Les cinq offres de bureaux testées</h2><p>Échantillon des cinq premières offres disposant d’une adresse explicite dans la page collectée. Les surfaces sont annoncées à la location et peuvent correspondre à plusieurs lots.</p><table><thead><tr><th>Adresse et annonce source</th><th>Surface annoncée</th><th>Aménités dans les 500 m</th></tr></thead><tbody>{ot}</tbody></table><p class="notice"><strong>Les cinq fiches indiquent une disponibilité immédiate, mais aucune vacance physique n’est certifiée.</strong> Une annonce de location ne démontre pas que l’immeuble entier est vide, libre de bail ou transformable. La couche porte donc le libellé « Bureaux · offres broker ». Pour un usage industriel, obtenir un cadre de collecte ou un flux du broker ; aucune licence ouverte de son catalogue n’est identifiée.</p><h2>Géographie et qualité</h2><ul><li>30 établissements scolaires retenus sur 33 entrées (structures médico-sociales et service administratif exclus). Le point source de l’école Marianne Picard se trouvait hors Suresnes ; sa position a été corrigée par géocodage du 28 rue Pagès via la <a href="{S['ban']['url']}">BAN / IGN</a>.</li><li>13 structures de soins sélectionnées sur 81 établissements FINESS : hôpital, SSR, psychiatrie, centres et maison de santé, soins non programmés, dialyse. Les établissements ne sont pas nécessairement des bâtiments distincts.</li><li>Une pharmacie a une localisation à la rue. Les points de bureaux localisent des adresses BAN, pas des emprises bâties. Au 13 boulevard Henri-Sellier, l’écart entre le point broker et le point BAN est de 94 m ; le point BAN est retenu. Le 72–74 rue Rouget-de-Lisle est représenté au numéro 74.</li><li>Les 55 géométries PLU sont valides, mais leur union couvre 99,5368 % du contour communal provenant d’une autre source. Petites superpositions de 64,86 m² conservées et signalées ; aucune correction arbitraire ni certification parcellaire.</li><li>Les distances de 500 m sont calculées sur l’ellipsoïde WGS84 entre les coordonnées sources. Elles sont à vol d’oiseau, sans réseau piéton ni obstacles. <strong>Les équipements hors Suresnes ne sont pas collectés</strong>, même lorsqu’un cercle dépasse la commune.</li><li>Le PLU du GPU doit être complété par la lecture du règlement, des OAP et des servitudes pour apprécier la faisabilité. L’exhaustivité et l’actualité des commerces OSM ne sont pas certifiées.</li></ul><h2>Livrables et vérification</h2><p>Les fichiers GeoJSON peuvent être importés dans un SIG. Chaque source est datée et reliée à un manifeste d’extraction (URL, code HTTP, horodatage, empreinte SHA-256). Les scripts conservent identifiants, méthode, exclusions et corrections. Aucun contact personnel, photo ou texte commercial intégral n’est repris dans la carte.</p><p>Tests navigateur : cinq interrupteurs indépendants, cinq rayons, clic sur repère, masquage/réactivation, retour à la ville, sources et mobile. Les captures et le compte rendu sont conservés localement. Ces tests valident le fonctionnement et la cohérence des données, pas la vacance ni la faisabilité.</p><p><a href="../processed/quality.json">Journal qualité</a> · <a href="../processed/sources.json">Registre des sources</a> · <a href="../suresnes-donnees.zip">Archive des données et scripts</a></p><footer>Instantané sans synchronisation automatique. Interlocuteur : François Allain ; responsable de maintenance à désigner avant industrialisation. © IGN, IDFM, Éducation nationale, FINESS, contributeurs OpenStreetMap ; annonces BNP Paribas Real Estate.</footer></body></html>'''
(R/'reports/rapport-suresnes.html').write_text(body)
with zipfile.ZipFile(R/'suresnes-donnees.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted(D.glob('*.geojson')):z.write(p,'processed/'+p.name)
 for name in ['sources.json','quality.json','extraction-manifest.json']:z.write(D/name,'processed/'+name)
 for p in sorted((R/'scripts').glob('*.py')):z.write(p,'scripts/'+p.name)
 for name in ['README.md','requirements.txt']:z.write(R/name,name)
 z.writestr('LISEZ-MOI.txt','Données géographiques du test Suresnes du 19 octobre 2026. Voir README.md et processed/sources.json. Les réponses originales sont conservées localement et peuvent être re-téléchargées avec les scripts. Le scraper produit les candidats et la sélection de cinq fiches. Aucun taux de vacance ne peut être déduit de cet échantillon.\n')
print('Report and archive ready', (R/'suresnes-donnees.zip').stat().st_size)
